47	  return [
48	    `[${f.severity.toUpperCase()}] ${f.rule}  ${loc}`,
49	    `  ${f.what}`,
50	    ...(f.why ? [`  Why: ${f.why}`] : []),
51	    `  Fix: ${f.fix}`,
52	    ...(f.doc ? [`  More: ${f.doc}`] : []),
53	  ].join('\n');
54	}
